S=[['希腊 stratos + agein／agos → strategos','军队 + 带领／领导者 → 将军、统帅']]
SY=S+[['希腊 strategia → 法语 stratégie 等借入路线','将军的职务、统率本领'],['英语 strategy','作战统筹 → 为实现目标作整体安排']]
SC=S+[['希腊 strategikos → 法语 stratégique／拉丁化形式','属于统帅的、适于指挥的'],['英语 strategic','战略的；对整体目标重要的']]
G=SY+[['英语 geo- + strategy → geostrategy','地理因素 + 战略 → 地缘战略']]
def A(h,w,m):return h+[[w,m]]
W=[
E('strategy','/ˈstrætədʒi/','战略；策略；实现目标的整体安排','像统帅看整张地图：目标在哪里，手里有什么，先走哪条路。','希腊 stratos“军队” + agos“领导者”形成 strategos；相关 strategia 经法语等路线进入英语。',SY,'a strategy for learning 是为了学会东西而安排的方法与取舍；a business strategy 说企业怎么达到目标。它不必是很长的文件，关键是动作之间有方向和关系，不只是把任务随便列在一起。','a strategy for；develop a strategy；put a strategy into practice。','strategy 常说整体方向与安排；tactics 常说某一步怎样执行。两者相互配合，并非一个永远抽象、一个永远短期。',('Our strategy is to master the common words before studying rare ones.','我们的策略是先掌握常用词，再学少见词。'),('The team changed its strategy after the first trial failed.','第一次试验失败后，团队调整了策略。'),sources=['https://www.etymonline.com/word/strategy']),
E('strategic','/strəˈtiːdʒɪk/','战略性的；有助于整体目标的；处于关键位置的','这一步不只是眼前方便，它会影响后面整盘怎么走。','接希腊 strategikos，经法语或拉丁化形式借入；现代可联系 strategy，但不是必须先有英语名词再拼形容词。',SC,'a strategic decision 会影响总体方向；a strategic location 是对目标很关键的位置，例如连接几条路线的地点。日常也可说有计划地选择时机，不限于战争。','strategic planning；a strategic decision；strategic importance。','important 只是重要；strategic 更突出它怎样影响整体计划、资源安排或位置优势。',('The company made a strategic decision to focus on one product.','公司作出了集中做好一款产品的战略决定。'),('The warehouse occupies a strategic location near the main roads.','仓库位于主要道路附近的关键位置。'),sources=['https://www.etymonline.com/word/strategic']),
E('strategically','/strəˈtiːdʒɪkli/','从战略上；有策略地；为整体效果有意安排地','不是随手放一下、随口做决定，而是考虑过它能怎样服务于目标。','strategic + -ally；常读成末尾 /kli/，不必逐个字母读出。',A(SC,'英语 strategically','按战略考虑；经过有目的的安排'),'strategically placed signs 是放在有用位置的标志；strategically important 是从全局看很重要。它可以描述很日常的小安排，不一定意味着重大军事计划。','strategically located；strategically important；think strategically。','randomly 是随机地；strategically 强调安排与目标的关系，但不保证安排一定高明。',('The signs were strategically placed at every junction.','标志被有意设置在每个岔路口，方便指引方向。'),('We need to think strategically about how to use the remaining time.','我们需要从整体上考虑怎样利用剩余时间。')),
E('strategist','/ˈstrætədʒɪst/','战略家；制定策略的人','站远一点看全局，把资源、时机和行动连成一套方案的人。','现代可按 strategy + -ist 理解；也有法语 stratégiste 的借入解释，后者同样来自 stratégie。',S+[['希腊 strategia → 法语 stratégie／stratégiste','统率本领 → 战略、制定战略者'],['英语 strategist','擅长或负责制定策略的人']],'a brilliant strategist 是善于总体谋划的人。商业、体育、政治等领域都能使用这个词，不要求本人一定是军人，也不要求担任最高领导。','a military strategist；a business strategist；a skilled strategist。','strategist 负责谋划总体安排；tactician 更突出具体行动技巧。实际工作中同一个人可能兼具两种能力。',('The coach is an excellent strategist as well as a patient teacher.','这位教练既擅长谋划，也是一位耐心的老师。'),('The strategist compared three possible routes for the project.','策略制定者比较了项目的三种可能路径。'),sources=['https://www.etymonline.com/word/strategist','https://en.wiktionary.org/wiki/strategist']),
E('strategize','/ˈstrætədʒaɪz/','制定策略；谋划','先别急着动手，把想达成什么、怎样做到想清楚。','strategy 去掉词尾 y 后接 -ize，形成动词。',A(SY,'英语 strategize','进行策略制定、谋划'),'strategize about a launch 是谋划发布安排；strategize how to do something 是思考实现路径。它可以用于团队讨论，但过多使用也容易让简单的 plan 显得不必要地复杂。','strategize about；strategize how to；meet to strategize。','plan 可以是一般安排；strategize 更强调目标、资源和路径之间的选择。',('The team met to strategize about the next stage.','团队开会谋划下一阶段的安排。'),('We spent the morning strategizing how to reach more readers.','我们用了一上午思考怎样触达更多读者。'),sources=['https://www.etymonline.com/word/strategize']),
E('strategise','/ˈstrætɪdʒaɪz/','制定策略；谋划〔常见英式拼写〕','与 strategize 一样，把行动之前的谋划作为一个动词来说。','strategy + -ise，是 strategize 的另一拼写形式，-ise 与 -ize 在这类词中对应。',A(SY,'英语 strategise／strategize','制定策略的两种拼写'),'英式文本里常见 strategise，美式通常用 strategize。意思不因为 s、z 改变；写一篇文章时跟随选定的拼写习惯，保持一致即可。','strategise for；strategise about；strategise how to。','strategise 与 strategize 不是两种不同策略，主要区别是拼写习惯。英国英语也使用 -ize，不宜说 s 才是唯一英式写法。',('The organisers need time to strategise before the event.','组织者需要在活动前留出时间谋划。'),('We should strategise together instead of making separate plans.','我们应该一起制定策略，而不是各自做计划。'),sources=['https://www.collinsdictionary.com/dictionary/english/strategise']),
E('strategizing','/ˈstrætədʒaɪzɪŋ/','正在谋划；制定策略的过程','把“想清全局、安排路径”的过程放到眼前。','strategize 去词尾 e + -ing。',A(SY,'英语 strategize → strategizing','制定策略 → 正在谋划、谋划过程'),'They are strategizing 是他们正在讨论策略；too much strategizing 可以批评一直想、迟迟不做。它既可组成进行时，也可作名词性成分。','spend time strategizing；constant strategizing；strategizing about。','strategy 是形成的策略或策略思想；strategizing 强调形成、调整策略的活动过程。',('They are strategizing about how to manage the larger workload.','他们正在谋划怎样处理更大的工作量。'),('After an hour of strategizing, we agreed on the first step.','谋划了一个小时后，我们确定了第一步。')),
E('strategical','/strəˈtiːdʒɪkəl/','战略的；策略上的〔较少见〕','与整盘安排有关，是 strategic 的另一形容词形式。','strategic + -al；共同接希腊 strategikos。',A(SC,'英语 strategical','与战略、策略有关的另一形式'),'旧文或部分正式表达中会遇到 strategical considerations。通常可以按 strategic 理解；现代一般写作里 strategic 更常见，不需要给两者编出根本不同的意思。','strategical considerations；a strategical advantage。','strategic 与 strategical 大体同义；strategically 是副词，不是一个形容词的拼写错误。',('The historian examined the strategical importance of the pass.','历史学家考察了那处山口的战略重要性。'),('The chapter discusses the strategical choices available to the commander.','这一章讨论了指挥官当时可以作出的战略选择。'),sources=['https://www.etymonline.com/word/strategic']),
E('stratagem','/ˈstrætədʒəm/','计策；巧计；为取得优势而用的一招','不是整张地图，而是关键时刻让对方没料到的一步。','希腊 strategema“统帅的行动、计谋”，经拉丁语、意大利语、法语进入英语；与 strategy 并行借入。',S+[['希腊 strategein → strategema','担任统帅 → 统帅的手段、计策'],['拉丁 strategema → 意大利 stratagemma → 法语 stratagème','计谋、巧计'],['英语 stratagem','为达目的想出的招数，常带巧妙或欺敌意味']],'a clever stratagem 是一个巧计；a stratagem to buy time 是为了争取时间的一招。它常带耍手腕、迷惑对方的味道，但具体是否贬义要看情境。','a clever stratagem；devise a stratagem；a stratagem for。','strategy 常是整体谋划；stratagem 常是谋划中的一招，不能单凭词长短分好坏。',('The pause was a stratagem to gain more time.','那次暂停是为了争取更多时间而采取的一招。'),('The novel reveals the detective’s stratagem in the final chapter.','小说在最后一章揭示了侦探的巧计。'),sources=['https://www.etymonline.com/word/stratagem']),
E('strategus','/strəˈtiːɡəs/','古希腊将军、统帅〔历史用语〕','把 strategy 拉回它最初的人物画面：带领军队的那个人。','拉丁 strategus 接希腊 strategos，来自 stratos“军队”与“带领”的词族。',S+[['希腊 strategos → 拉丁 strategus → 英语 strategus','统帅；古代某些政体中的相关官职名称']],'阅读古希腊历史时，strategus 可以指统帅，也可能是带特定职责的官职。不要把现代公司里的 strategist 都叫 strategus；后者保留明显的历史名称色彩。','a Greek strategus；the office of strategus。','strategist 是制定策略的人；strategus 是古代统帅或相关官职，不是其普通单数变体。',('The chapter describes the duties of a Greek strategus.','这一章介绍了一位古希腊统帅的职责。'),('The inscription records the name of the strategus.','铭文记录了那位统帅的名字。'),sources=['https://www.merriam-webster.com/dictionary/strategus']),
E('stratocracy','英 /strəˈtɒkrəsi/；美 /strəˈtɑːkrəsi/','军人统治；以军队为基础的政体','军队不只是执行命令，也掌握了政府的统治权。','希腊 stratos“军队” + -cracy“统治、政体”。',[['希腊 stratos + -kratia 相关构词成分','军队 + 统治'],['英语 stratocracy','以军队为基础的统治或政府']],'这是政治学和历史文字里较少见的术语。重点在统治权由军队掌握，不能把任何拥有军队的国家都叫 stratocracy，也不能单凭一位官员有军旅经历就下结论。','a stratocracy；the concept of stratocracy。','militarism 是重视、推崇军事力量的一种倾向；stratocracy 描述军队掌权的政体关系。',('The lecture defined stratocracy as government based on military power.','讲座把 stratocracy 解释为以军事权力为基础的统治。'),('The author distinguishes stratocracy from civilian government with a large army.','作者区分了军人统治与拥有庞大军队的文官政府。'),sources=['https://www.merriam-webster.com/dictionary/stratocracy']),
E('stratography','构词参考 英 /strəˈtɒɡrəfi/；美 /strəˈtɑːɡrəfi/','军队状况记述〔罕见〕；另有地层描述义','这一支是把军队的组成、情况写下来；同拼写的地层用法要另找“层”的词源。','军队义为希腊 stratos + -graphy“记录、描述”；地层义则接拉丁 stratum 的层状支线，不能混成一条直接来源。',[['军队支线：希腊 stratos + -graphy','军队 + 描述'],['英语 stratography','对军队情况的记述'],['并行同形词：拉丁 stratum + -graphy','层 + 描述 → 地层描述']],'现在很少用作日常词。看到旧书里的 stratography，要根据上下文判断是在描述军队还是地层；如果主题是岩石，不要硬翻成军事记录。现代地学更常见 stratigraphy。','旧文中的 stratography；a work of stratography。','stratography 的军队义属本页；stratigraphy“地层学”接层状支线。两条词源可能有更远的共同背景，但英语构词时不能直接混用。',('The catalogue lists the old volume under stratography.','目录把那本旧书列在军队状况记述类下。'),('Here, stratography describes the army’s organisation, not rock layers.','这里的 stratography 描述军队编制，而不是岩层。'),sources=['https://www.etymonline.com/word/stratography','https://en.wiktionary.org/wiki/stratography']),
E('geostrategy','英 /ˌdʒiːəʊˈstrætədʒi/；美 /ˌdʒiːoʊˈstrætədʒi/','地缘战略','把地图也放进战略里：山海、通道、距离和资源位置会怎样影响选择。','geo-“地球、地理” + strategy。',G,'geostrategy 把地理条件与国家或地区的战略考虑连起来。它不是只给地图上色，而是问地点和空间关系为什么会影响行动方案。理解术语时不必先赞同某一种具体战略。','regional geostrategy；the study of geostrategy。','geography 研究地理环境与空间关系；geostrategy 更聚焦这些因素怎样参与战略选择。',('The course examines the role of geography in geostrategy.','这门课考察地理因素在地缘战略中的作用。'),('The book connects trade routes with regional geostrategy.','这本书把贸易路线与地区地缘战略联系起来。'),sources=['https://www.merriam-webster.com/dictionary/geostrategy']),
E('geostrategic','英 /ˌdʒiːəʊstrəˈtiːdʒɪk/；美 /ˌdʒiːoʊstrəˈtiːdʒɪk/','地缘战略的；因地理位置而有战略意义的','同样是一块地方，位置一变，它在全局里的作用也会变。','geo-“地理” + strategic“战略的”，与 geostrategy 对应。',SC+[['英语 geo- + strategic → geostrategic','结合地理位置、空间关系来理解的战略性质']],'geostrategic importance 说某处因位置等因素而具有战略意义。这个词描述一种分析角度；并不是说所有重要地点都必须具有相同价值。','geostrategic importance；geostrategic location；geostrategic considerations。','strategic 范围较宽；geostrategic 特别把地理和空间条件放进解释。',('The article explains the island’s geostrategic importance.','文章解释了那座岛屿的地缘战略重要性。'),('Geostrategic considerations shaped the discussion of the route.','有关地缘战略的考虑影响了对那条路线的讨论。'),sources=['https://www.merriam-webster.com/dictionary/geostrategy']),
E('geostrategist','英 /ˌdʒiːəʊˈstrætədʒɪst/；美 /ˌdʒiːoʊˈstrætədʒɪst/','地缘战略研究者、谋划者','习惯一边看地图、一边想全局安排的人。','geo- + strategist；也可理解为 geostrategy 对应的 -ist 人员名称。',G+[['英语 geostrategist','研究或制定地缘战略的人']],'geostrategist 可以指研究地理因素与战略关系的人，也可以指参与相应政策谋划的人。它标明专长，不自动说明这个人的判断就正确。','a geostrategist；the analysis of a geostrategist。','geographer 是地理学者；geostrategist 更专注战略问题，二者关注范围不同。',('The geostrategist compared the region’s land and sea routes.','地缘战略研究者比较了该地区的陆路与海路。'),('The panel included a historian and a geostrategist.','讨论小组里有一位历史学家和一位地缘战略研究者。'),sources=['https://www.merriam-webster.com/dictionary/geostrategy']),
]
ROOT=dict(id='C1431',meaning='军队；统率军队',core='STRAT = ARMY',image='一支军队分布在地图上，统帅必须把目标、路线和资源连成整体。“带领军队的本领”逐渐变成各领域的策略与谋划。',intro='本页的 strat- 来自希腊 stratos“军队”。stratos 与带领、领导者的成分相接形成 strategos“统帅”，再形成 strategy 所属的一大支。不要先把 strategy 想成空泛的口号；它最早有一个需要统筹许多人的具体场面。',forms='strateg- 出现在 strategy、strategic、strategist；strato- 出现在 stratocracy、stratography。strategy、strategic、stratagem 各有自己的历史借入路线，不能全部当成现代英语加后缀。拉丁 stratum“铺开的层”是另一条近层来源，stratosphere 并不是军队组成的天空。',branches=[['统筹整体行动','strategy, strategic, strategically, strategical, strategist'],['进行谋划','strategize, strategise, strategizing'],['用一招取得优势','stratagem'],['古代统帅与军队掌权','strategus, stratocracy'],['把军队情况写下来','stratography'],['把地理位置纳入整体考虑','geostrategy, geostrategic, geostrategist']],contrasts='strategy 是整体谋划，stratagem 常是一条具体巧计。strategist 是制定策略的人，strategus 是古代统帅名称。stratography 有军队、地层两条同形支线，本页只把军队义视为本词族的直接成员。',practice='The strategist asked us to explain our goal before choosing a strategy. A clever stratagem would help only if it served that goal.\n\n策略制定者让我们先说明目标，再选择策略。一个巧计只有服务于那个目标，才真正有帮助。',words=[w['word'] for w in W])
